// MONITOR + BOT V2 ADMIN. Per-girl views read this folder's logs/<girl>/ and data/<girl>/ (?girl=<slug>).
// The Bot V2 admin endpoints (/api/girls*) read clones rows and write ONLY two columns on them:
// clones.engine ('live' | 'v2') and clones.v2_vars (her V2 details). Nothing else in Supabase is written.
//
// Run:   npm run dash          (http://127.0.0.1:4300, plus this machine's Tailscale IP if it has one)
// Stop:  screen -S girlbot-dash -X quit
import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { execSync } from "node:child_process";
import { config, ROOT } from "../src/config.js";
import { getGirl } from "../src/girls/index.js";
import { runAs, currentGirl, girlDataDir, girlLogDir } from "../src/context.js";
import { FLEET_FILE } from "../src/fleet.js";
import { purchases, refunds, priceMode, ownedKeys } from "../src/payments.js";
import { readOffers } from "../src/bundle-offers.js";
import { TIP_SETTING_COLUMNS, tipSettingsFromRow } from "../src/tips/settings.js";
import { TEMPLATE, VAR_NAMES, VAR_HELP, renderParts, validateVars, previewParts } from "../src/girls/template.js";
import { mapFromV1 } from "../src/girls/map-v1.js";
import { runHandover, clearHandover } from "../src/handover.js";
import { ArchiveQueue } from "../src/archive/queue.js";
import { chatHistory } from "./history.js";

const PORT = Number(process.env.DASH_PORT ?? 4300);
const girl = getGirl(config.girl); // the local test girl (prompt editor on "/")
const LOG_ROOT = config.logDir;

const readLines = (f: string): string[] => {
  try { return fs.readFileSync(f, "utf8").split("\n").filter(Boolean); } catch { return []; }
};
const readJsonl = (f: string): any[] => readLines(f).map((l) => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);

/** turns.log blocks from before requests.jsonl existed. */
function legacyTurns(): any[] {
  const out: any[] = [];
  let cur: any = null;
  for (const line of readLines(path.join(girlLogDir(), "turns.log"))) {
    const h = line.match(/^(\S+Z) \| (.*?) \| (.*?) \| (\d+)ms \| (.*?) \| in=(\d+) out=(\d+) \$([\d.]+)/);
    if (h) {
      cur = { ts: h[1], chatId: h[2], note: h[3], ms: +h[4], provider: h[5], tokensIn: +h[6], tokensOut: +h[7], cost: +h[8], legacy: true };
      out.push(cur);
    } else if (cur) {
      const m = line.match(/^\s+(FAN|HER|MEDIA): (.*)$/);
      if (m?.[1] === "FAN") cur.fanText = m[2];
      if (m?.[1] === "HER") cur.final = [m[2]];
      if (m?.[1] === "MEDIA") cur.mediaLine = m[2];
    }
  }
  return out;
}

export function turns(): any[] {
  const full = readJsonl(path.join(girlLogDir(), "requests.jsonl"));
  const firstFull = full[0]?.ts ?? "9999";
  return [...legacyTurns().filter((t) => t.ts < firstFull), ...full].sort((a, b) => (a.ts < b.ts ? 1 : -1));
}

function botProcess() {
  try {
    const ps = execSync(`ps -eo pid,etimes,args | grep "${ROOT}/node_modules/.bin/tsx src/bot.ts" | grep -v grep`, { encoding: "utf8" }).trim();
    const [pid, secs] = ps.split(/\s+/);
    return { running: true, pid: +pid, upSeconds: +secs };
  } catch { return { running: false }; }
}

// ---------- delivery evidence (Stage 1.1) ----------
// A request row written by Stage 1.1 or later carries `delivery`: its `media` is ONLY media Telegram acknowledged.
// Older rows (and turns.log blocks from before requests.jsonl) have no delivery evidence: their media was merely selected,
// so they are counted apart as "unverified" and never as confirmed sends or confirmed failures.
// Rows from the simulator (mode "simulated") are never live deliveries: they are left out of every count.
const isLive = (t: any) => t.mode !== "simulated";
const hasEvidence = (t: any) => !!t.delivery;
const selectedOnly = (t: any) => !hasEvidence(t) && (!!t.media || !!t.mediaLine);
const mediaFree = (t: any) => (t.media ? !!t.media.free : /^FREE/.test(String(t.mediaLine ?? "")));

export function stats(all: any[]) {
  const day = Date.now() - 24 * 3600_000;
  const recent = all.filter((t) => Date.parse(t.ts) >= day);
  const sum = (a: any[], k: string) => a.reduce((s, t) => s + (Number(t[k]) || 0), 0);
  const by = (a: any[], f: (t: any) => string) => a.reduce((m: Record<string, number>, t) => { const k = f(t) || "?"; m[k] = (m[k] ?? 0) + 1; return m; }, {});
  const block = (rows: any[]) => {
    const a = rows.filter(isLive);
    const confirmed = a.filter((t) => hasEvidence(t) && t.media); // Telegram acknowledged this media
    const unverified = a.filter(selectedOnly);
    return {
      turns: a.length, avgMs: a.length ? Math.round(sum(a, "ms") / a.length) : 0, costUsd: +sum(a, "cost").toFixed(5),
      tokensIn: sum(a, "tokensIn"), tokensOut: sum(a, "tokensOut"),
      providers: by(a, (t) => t.provider), notes: by(a, (t) => String(t.note).split(":")[0]),
      lockedSent: confirmed.filter((t) => !t.media.free).length, freeSent: confirmed.filter((t) => t.media.free).length, // confirmed only
      lockedStarsShown: confirmed.reduce((s, t) => s + (t.media.free ? 0 : Number(t.media.stars) || 0), 0), // the Stars actually passed to Telegram
      mediaNotConfirmed: a.filter((t) => hasEvidence(t) && t.selectedMedia && !t.media).length, // selected, but Telegram never acknowledged it
      unverified: { locked: unverified.filter((t) => !mediaFree(t)).length, free: unverified.filter(mediaFree).length }, // older rows: delivery never verified
      simulatedExcluded: rows.length - a.length,
    };
  };
  return { last24h: block(recent), allTime: block(all) };
}

export function chats() {
  let files: string[] = [];
  try { files = fs.readdirSync(girlDataDir()).filter((f) => f.endsWith(".json") && !f.startsWith("_")); } catch {}
  return files.map((f) => {
    const p = path.join(girlDataDir(), f);
    const c = JSON.parse(fs.readFileSync(p, "utf8"));
    return { id: f.replace(/\.json$/, ""), ageConfirmed: !!c.ageConfirmed, messages: c.history?.length ?? 0, sent: c.sent?.length ?? 0,
      updated: fs.statSync(p).mtime.toISOString(), history: c.history ?? [], sentKeys: c.sent ?? [], who: c.who ?? null, bcid: c.bcid ?? null, owned: [...ownedKeys(f.replace(/\.json$/, ""))] };
  }).sort((a, b) => (a.updated < b.updated ? 1 : -1));
}

/** Stage 3: which of her bundles are sellable and, for every other one, the reason it is left out (written by the runner on each catalogue refresh). */
export function bundlesInfo(): { at: string; listed: { id: string; name: string; files: number; stars: number }[]; excluded: { id: string; name: string; reason: string }[] } | null {
  try { return JSON.parse(fs.readFileSync(path.join(girlDataDir(), "_bundle_exclusions.json"), "utf8")); } catch { return null; }
}

const SECRET = /KEY|TOKEN|SECRET/i;
function status() {
  const out = readLines(path.join(LOG_ROOT, "bot.out"));
  return {
    bot: botProcess(),
    girl: { slug: girl.slug, name: girl.name, cloneId: girl.cloneId },
    catalogueLine: [...out].reverse().find((l) => l.startsWith("[media]")) ?? null,
    bundles: bundlesInfo(),
    settings: Object.fromEntries(Object.entries(config).filter(([k]) => !SECRET.test(k) && !/supabaseUrl/.test(k))),
    env: Object.fromEntries(["TELEGRAM_BOT_TOKEN", "OPENROUTER_API_KEY", "SUPABASE_URL", "SUPABASE_SERVICE_KEY", "ELEVENLABS_API_KEY"].map((k) => [k, !!process.env[k]])),
    files: Object.fromEntries(["turns.log", "requests.jsonl", "blocked.jsonl", "bot.out"].map((f) => {
      try { const s = fs.statSync(path.join(f === "bot.out" ? LOG_ROOT : girlLogDir(), f)); return [f, { bytes: s.size, updated: s.mtime.toISOString() }]; } catch { return [f, null]; }
    })),
  };
}

function prompt() {
  const vars = girl.vars;
  return { girl: { name: girl.name, slug: girl.slug }, varNames: VAR_NAMES, help: VAR_HELP, vars, parts: renderParts(vars),
    greeting: girl.greeting, settings: Object.fromEntries(Object.entries(config).filter(([k]) => !SECRET.test(k) && !/supabaseUrl|Dir$/.test(k))) };
}

/** Save edited variables. Validated first; written atomically; the bot reads them on its next reply. */
function saveVars(body: string): { ok: boolean; errors?: string[] } {
  let v: Record<string, unknown>;
  try { v = JSON.parse(body); } catch { return { ok: false, errors: ["not JSON"] }; }
  const errors = validateVars(v);
  if (errors.length) return { ok: false, errors };
  const tmp = `${girl.varsFile}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(v, null, 2) + "\n");
  fs.copyFileSync(girl.varsFile, `${girl.varsFile}.bak`); // previous version, one step back
  fs.renameSync(tmp, girl.varsFile);
  console.log(`[monitor] ${girl.slug} variables saved`);
  return { ok: true };
}

/** Sales from the Stars ledger, plus the offers the turn log can vouch for. */
export function sales() {
  const ps = purchases().sort((a, b) => (a.ts < b.ts ? 1 : -1));
  const labels = new Map<string, string>();
  const rows = readJsonl(path.join(girlLogDir(), "requests.jsonl")).filter(isLive);
  for (const t of rows) { const m = t.media ?? t.selectedMedia; if (m && !m.free) labels.set(m.key, m.label); }
  const confirmed = rows.filter((t) => hasEvidence(t) && t.media && !t.media.free).length; // locked cards Telegram acknowledged
  const unverified = rows.filter((t) => selectedOnly(t) && !mediaFree(t)).length; // older rows: selected, delivery never verified
  const chatsById = new Map(chats().map((c) => [c.id, c]));
  const fanOf = (id: number) => chatsById.get(String(id))?.who ?? String(id);
  const offers = ps.some((p) => p.offerId) ? readOffers().offers : new Map();
  // A bundle sale names the bundle, the offer (the immutable quote) and the exact files that were in that card.
  const bundleOf = (p: (typeof ps)[number]) => {
    if (p.kind !== "bundle") return undefined;
    const o = p.offerId ? offers.get(p.offerId) : undefined;
    return { bundleId: p.itemKey.slice("bundle:".length), offerId: p.offerId ?? null, name: o?.name ?? null, files: o ? o.files.map((f: any) => ({ n: f.n, kind: f.kind, label: f.label })) : null, quotedStars: o?.stars ?? null, storedStars: o?.storedStars ?? null,
      note: o ? undefined : "the quoted file list is not on this machine" };
  };
  return {
    priceMode: priceMode(),
    purchases: ps.map((p) => { const b = bundleOf(p); return { ...p, label: b ? `bundle${b.name ? ` "${b.name}"` : ""} of ${b.files ? b.files.length : "?"} files` : labels.get(p.itemKey) ?? null, fan: fanOf(p.chatId), ...(b ? { bundle: b } : {}) }; }),
    totals: { stars: ps.reduce((s, p) => s + p.stars, 0), count: ps.length, buyers: new Set(ps.map((p) => p.chatId)).size, refunds: refunds().length },
    // No conversion rate: purchases are all-time (ledger), confirmed offers only exist since delivery tracking began and older
    // offers were never verified, so no honest comparable denominator exists.
    offers: { confirmed, unverified, unlocked: ps.length, rate: null as number | null, rateNote: "unavailable: offers before delivery tracking were never verified" },
  };
}

/** One row per fan: chat file + his turns + his purchases. */
export function fans() {
  const ps = purchases();
  const ts = readJsonl(path.join(girlLogDir(), "requests.jsonl"));
  return chats().map((c) => {
    const mine = ts.filter((t) => String(t.chatId) === c.id && isLive(t));
    const bought = ps.filter((p) => String(p.chatId) === c.id);
    return {
      chatId: c.id, name: c.who ?? null, username: c.who?.startsWith("@") ? c.who.slice(1) : null, business: !!c.bcid,
      firstSeen: mine[0]?.ts ?? null, lastSeen: mine.at(-1)?.ts ?? c.updated, messages: c.messages,
      offered: mine.filter((t) => hasEvidence(t) && t.media && !t.media.free).length, // locked cards Telegram acknowledged
      offeredUnverified: mine.filter((t) => selectedOnly(t) && !mediaFree(t)).length, // older rows: selected, delivery never verified
      bought: bought.length, starsSpent: bought.reduce((s, p) => s + p.stars, 0),
    };
  });
}

/** One request row, selected by its logged turn id (the id exists only in logs; chat messages carry none). */
export function requestByTurn(turnId: string | null): any {
  if (!turnId) return { error: "no turn id given" };
  const row = readJsonl(path.join(girlLogDir(), "requests.jsonl")).reverse().find((t) => t.turnId === turnId);
  return row ?? { error: "no request row has that turn id" };
}

// ---------- Bot V2 admin: which girls run on V2, their details, their connections ----------
const sb = async (pathQ: string, init: RequestInit = {}) => {
  const res = await fetch(`${config.supabaseUrl}/rest/v1/${pathQ}`, {
    ...init,
    headers: { apikey: config.supabaseKey, Authorization: `Bearer ${config.supabaseKey}`, "Content-Type": "application/json", Prefer: "return=minimal", ...(init.headers ?? {}) },
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok) throw new Error(`supabase ${res.status}: ${(await res.text()).slice(0, 160)}`);
  return res.status === 204 ? null : res.json();
};
type CloneRow = {
  id: string; slug: string; name: string; status: string; engine?: string; v2_vars?: Record<string, string> | null;
  // Stage 2B: the creator's SAVED credit settings (absent before the credits migration is applied)
  v2_credits_enabled?: boolean; v2_credits_pack_quantity?: number; v2_credits_pack_stars?: number; v2_credits_revision?: number;
};
const CREDIT_COLS = "v2_credits_enabled,v2_credits_pack_quantity,v2_credits_pack_stars,v2_credits_revision";
/** PostgREST's positive "that column does not exist" answer (HTTP 400, 42703). Anything else (network, 5xx, timeout) is NOT absence. */
export const columnAbsent = (e: unknown) => /supabase 400/.test(String((e as any)?.message ?? e)) && /42703|PGRST204|column .*does not exist/i.test(String((e as any)?.message ?? e));
async function cloneRows(): Promise<CloneRow[]> {
  // The credit columns are read first. Only a POSITIVE "column does not exist" falls back to the older column lists (before the
  // migrations); any other failure is raised, so an unreadable credit state is never displayed or acted on as "not installed".
  try { return await sb(`clones?select=id,slug,name,status,engine,v2_vars,${CREDIT_COLS}&order=name.asc`); }
  catch (e) { if (!columnAbsent(e)) throw e; }
  try { return await sb("clones?select=id,slug,name,status,engine,v2_vars&order=name.asc"); }
  catch (e) { if (!columnAbsent(e)) throw e; }
  return (await sb("clones?select=id,slug,name,status&order=name.asc")).map((r: CloneRow) => ({ ...r, engine: "live", v2_vars: null })); // before the migration
}
/** Strict, per-creator read of the credit switch used by the engine button: installed / positively absent / unreadable (=> refuse). */
async function creditSwitch(id: string): Promise<{ state: "installed"; enabled: boolean } | { state: "absent" } | { state: "unreadable"; error: string }> {
  try {
    const r = await sb(`clones?id=eq.${encodeURIComponent(id)}&select=v2_credits_enabled`);
    if (!Array.isArray(r) || r.length !== 1) return { state: "unreadable", error: "creator not found" };
    return { state: "installed", enabled: r[0].v2_credits_enabled !== false };
  } catch (e) { return columnAbsent(e) ? { state: "absent" } : { state: "unreadable", error: String((e as any)?.message ?? e).slice(0, 120) }; }
}
/** Open metered work for the creator, strict: any failure is "unknown" (the caller refuses). */
async function openMetered(id: string): Promise<{ ok: true; reserved: number } | { ok: false; error: string }> {
  try {
    const w = await rpc("v2credit_open_work", { p_clone_id: id });
    if (!w || w.ok !== true || typeof w.reserved_turns !== "number" || !Number.isFinite(w.reserved_turns) || w.reserved_turns < 0) return { ok: false, error: "unexpected open-work answer" };
    return { ok: true, reserved: w.reserved_turns };
  } catch (e) { return { ok: false, error: String((e as any)?.message ?? e).slice(0, 120) }; }
}
/** Database RPC through the service key (the credits functions are service_role only). */
async function rpc(fn: string, args: Record<string, unknown>): Promise<any> {
  const res = await fetch(`${config.supabaseUrl}/rest/v1/rpc/${fn}`, {
    method: "POST", headers: { apikey: config.supabaseKey, Authorization: `Bearer ${config.supabaseKey}`, "Content-Type": "application/json" },
    body: JSON.stringify(args), signal: AbortSignal.timeout(8_000),
  });
  const text = await res.text();
  if (!res.ok) throw Object.assign(new Error(`rpc ${fn} ${res.status}: ${text.slice(0, 160)}`), { status: res.status, body: text });
  return text ? JSON.parse(text) : null;
}
const notInstalled = (e: any) => e?.status === 404 || /PGRST202|42883|42703|does not exist|schema cache/i.test(String(e?.body ?? e?.message ?? ""));

/** Saved (database) settings next to what the running bot has APPLIED. A pending change is never shown as live. */
function creditView(row: CloneRow) {
  const installed = row.v2_credits_enabled !== undefined;
  const saved = installed ? { enabled: row.v2_credits_enabled === true, packQuantity: Number(row.v2_credits_pack_quantity), packStars: Number(row.v2_credits_pack_stars), revision: Number(row.v2_credits_revision) } : null;
  const rt = (readJson(FLEET_FILE())?.girls ?? {})[row.slug]?.credits ?? null;
  const applied = rt?.applied ?? null;
  const inSync = !!saved && !!applied && applied.revision === saved.revision && applied.enabled === saved.enabled;
  return { installed, saved, runtime: rt, applied, inSync, pending: installed && !inSync && row.engine === "v2" };
}
const readJson = (f: string) => { try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return null; } };
/** Starting point for her details: Riley's hand-written set for Riley, empty boxes for anyone else (never another girl's facts). */
function templateFor(row: CloneRow): Record<string, string> {
  if (row.id === getGirl("riley").cloneId) return getGirl("riley").vars as unknown as Record<string, string>;
  return Object.fromEntries(VAR_NAMES.map((k) => [k, ""]));
}
async function girls() {
  const fleet = readJson(FLEET_FILE())?.girls ?? {};
  return (await cloneRows()).filter((r) => r.slug !== "hazey-haley").map((r) => {
    const errs = r.v2_vars ? validateVars(r.v2_vars) : ["no details saved"];
    const owners = readJson(path.join(girlDataDir(r.slug), "_business.json")) ?? {};
    return {
      id: r.id, slug: r.slug, name: r.name, status: r.status, engine: r.engine === "v2" ? "v2" : "live",
      detailsReady: errs.length === 0, missing: errs,
      runtime: fleet[r.slug] ? { state: fleet[r.slug].status, error: fleet[r.slug].error, botUsername: fleet[r.slug].botUsername, startedAt: fleet[r.slug].startedAt } : null,
      credits: creditView(r),
      business: Object.entries(owners).map(([id, ownerId]) => ({ id, ownerId, enabled: true })),
    };
  });
}
export async function setEngine(body: any) {
  let rows: CloneRow[];
  try { rows = await cloneRows(); } catch { return { ok: false, error: "Could not read the creators just now, so the engine was not switched. Try again in a minute." }; }
  const row = rows.find((r) => r.id === body?.id);
  if (!row) return { ok: false, error: "unknown girl" };
  if (body.engine !== "live" && body.engine !== "v2") return { ok: false, error: "engine must be live or v2" };
  if (body.engine === "v2") {
    const errs = row.v2_vars ? validateVars(row.v2_vars) : ["no details saved"];
    if (errs.length) return { ok: false, error: `save her details first: ${errs.slice(0, 3).join(", ")}` };
  }
  // Stage 2B: the agreed sequence. Charging must already be off and nothing open; then, leaving V2, the runner is stopped and drained by the
  // fleet (VERIFIED) and only after that is clones.engine written. Every read fails closed; only a positively established
  // pre-migration state (the credit column does not exist) skips this and behaves exactly as before.
  const sw = await creditSwitch(row.id);
  if (sw.state === "unreadable") return { ok: false, error: "Could not check whether message credits are active for this creator, so the engine was not switched. Try again in a minute." };
  if (sw.state === "installed") {
    if (sw.enabled) return { ok: false, error: "Message credits are enabled for this creator. Turn them off, wait for open replies to finish, then switch engines." };
    const before = await openMetered(row.id);
    if (!before.ok) return { ok: false, error: "Could not check whether metered replies are still open, so the engine was not switched. Try again in a minute." };
    if (before.reserved > 0) return { ok: false, error: `${before.reserved} metered replies are still unresolved. Wait for them to finish or expire, then try again.` };
    if (body.engine === "live" && row.engine === "v2") {
      const h = await runHandover(config.dataDir, row.slug);
      try {
        if (!h.ok) return { ok: false, error: `The bot could not confirm that every reply was finished (${JSON.stringify(h.detail).slice(0, 160)}). The engine was not switched.` };
        const after = await openMetered(row.id); // verify again, from the database, after the drain and before the write
        if (!after.ok || after.reserved > 0) return { ok: false, error: "After stopping the bot, metered replies are still open or could not be verified. The engine was not switched." };
        await sb(`clones?id=eq.${row.id}`, { method: "PATCH", body: JSON.stringify({ engine: body.engine }) });
        console.log(`[monitor] ${row.slug} engine -> ${body.engine} (verified hand-over)`);
        return { ok: true };
      } finally { clearHandover(config.dataDir, row.slug); } // the fleet may start the runner again if the switch did not happen
    }
  }
  await sb(`clones?id=eq.${row.id}`, { method: "PATCH", body: JSON.stringify({ engine: body.engine }) });
  console.log(`[monitor] ${row.slug} engine -> ${body.engine}`);
  return { ok: true };
}
async function details(slug: string) {
  const row = (await cloneRows()).find((r) => r.slug === slug);
  if (!row) return { error: "unknown girl" };
  const vars = row.v2_vars ?? null;
  const errors = vars ? validateVars(vars) : ["no details saved"];
  // The hardcoded template is always shown; empty variables are just empty coloured slots.
  return { varNames: VAR_NAMES, help: VAR_HELP, vars, template: templateFor(row), parts: previewParts(vars ?? {}), errors };
}
/** "Fill from V1": her V1 profile fields mapped onto the V2 variables. Read only; nothing is saved here. */
async function mapDetails(slug: string) {
  const rows = await sb(`clones?slug=eq.${encodeURIComponent(slug)}&select=*`);
  const row = rows?.[0];
  if (!row) return { error: "unknown girl" };
  delete row.bot_token;
  return mapFromV1(row);
}
async function saveDetails(body: any) {
  const row = (await cloneRows()).find((r) => r.slug === body?.girl);
  if (!row) return { ok: false, errors: ["unknown girl"] };
  const v = body.vars ?? {};
  const errors = validateVars(v);
  if (errors.length) return { ok: false, errors };
  await sb(`clones?id=eq.${row.id}`, { method: "PATCH", body: JSON.stringify({ v2_vars: v }) });
  console.log(`[monitor] ${row.slug} V2 details saved`);
  return { ok: true, parts: renderParts(v) };
}

/**
 * The ONE server-validated credit settings path (contract 5.1): enabled / pack size / price, validated again by the database function.
 * Applies to FUTURE quotes and turns only; the running bot picks it up on its next fleet refresh (the view shows saved vs applied).
 */
async function saveCreditSettings(body: any) {
  const row = (await cloneRows()).find((r) => r.id === body?.id);
  if (!row) return { ok: false, error: "unknown girl" };
  if (row.v2_credits_enabled === undefined) return { ok: false, error: "message credits are not installed on the database yet" };
  const args: Record<string, unknown> = { p_clone_id: row.id, p_actor: "v2-monitor" };
  if (body.enabled !== undefined) { if (typeof body.enabled !== "boolean") return { ok: false, error: "enabled must be true or false" }; args.p_enabled = body.enabled; }
  for (const [k, a, lo, hi] of [["packQuantity", "p_pack_quantity", 1, 1000], ["packStars", "p_pack_stars", 1, 10000]] as const) {
    if (body[k] === undefined) continue;
    const n = Number(body[k]);
    if (!Number.isInteger(n) || n < lo || n > hi) return { ok: false, error: `${k} must be a whole number from ${lo} to ${hi}` };
    args[a] = n;
  }
  try {
    const r = await rpc("v2credit_set_settings", args);
    if (!r || r.ok !== true) return { ok: false, error: String(r?.message ?? "settings refused") };
    console.log(`[monitor] ${row.slug} credit settings saved: ${JSON.stringify({ enabled: r.enabled, packQuantity: r.pack_quantity, packStars: r.pack_stars, revision: r.revision })}`);
    return { ok: true, saved: { enabled: r.enabled, packQuantity: r.pack_quantity, packStars: r.pack_stars, revision: r.revision }, changed: r.changed === true };
  } catch (e: any) { return { ok: false, error: String(e?.message ?? e).slice(0, 160) }; }
}
/** Runtime credit state for one girl (the per-fan files are read-only here). */
async function creditsFor(slug: string) {
  const row = (await cloneRows()).find((r) => r.slug === slug);
  if (!row) return { error: "unknown girl" };
  const view = creditView(row);
  let openWork: unknown = null;
  if (view.installed) { try { openWork = await rpc("v2credit_open_work", { p_clone_id: row.id }); } catch (e: any) { openWork = { error: String(e?.message ?? e).slice(0, 120) }; } }
  const state = readJson(path.join(girlDataDir(slug), "_credit_state.json")) ?? { pending: {}, offered: {} };
  return { ...view, openWork, pendingTurns: Object.keys(state.pending ?? {}).length, offersThisEpisode: Object.keys(state.offered ?? {}).length };
}

/**
 * Stage 4: the tip product for one girl. SAVED settings (her clones row, the existing V1 columns) next to what the running bot has APPLIED, the
 * runtime counters the runner publishes (offers, receipts), and the database's open work. Read only; any unreadable part says so instead of guessing.
 */
async function tipsFor(slug: string) {
  const row = (await cloneRows()).find((r) => r.slug === slug);
  if (!row) return { error: "unknown girl" };
  let saved: ReturnType<typeof tipSettingsFromRow> | null = null, savedProblem: string | undefined;
  try { const r = await sb(`clones?id=eq.${encodeURIComponent(row.id)}&select=${TIP_SETTING_COLUMNS}`); saved = Array.isArray(r) && r.length === 1 ? tipSettingsFromRow(r[0]) : null; }
  catch (e) { savedProblem = columnAbsent(e) ? "the tip settings columns are not on the database" : String((e as any)?.message ?? e).slice(0, 120); }
  const rt = (readJson(FLEET_FILE())?.girls ?? {})[slug]?.tips ?? null;
  let openWork: unknown = null;
  try { openWork = await rpc("v2tip_open_work", { p_clone_id: row.id }); } catch (e: any) { openWork = notInstalled(e) ? { notInstalled: true } : { error: String(e?.message ?? e).slice(0, 120) }; }
  const applied = rt?.applied ?? null;
  const inSync = !!saved && !!applied && saved.enabled === applied.enabled && JSON.stringify(saved.choices) === JSON.stringify(applied.choices) && saved.maxStars === applied.maxStars;
  return { saved, savedProblem, applied, offersEnabled: rt?.offersEnabled ?? false, offers: rt?.offers ?? null, receipts: rt?.receipts ?? null, handover: rt?.handover ?? null, openWork, inSync, pending: !!saved && !inSync && row.engine === "v2" };
}

/**
 * Stage 5: the archive + memory for one girl. SAVED switch (her clones row) next to what the running bot has APPLIED, the local archive queue read
 * straight from its file (pending, dead letters), the database's own worker totals (runs, tokens, REAL cost), and the fans the worker has parked.
 * Read only: nothing here writes, queues or flushes anything. Any unreadable part says so instead of guessing.
 */
export async function memoryFor(slug: string) {
  const row = (await cloneRows()).find((r) => r.slug === slug);
  if (!row) return { error: "unknown girl" };
  let saved: { enabled: boolean } | null = null, savedProblem: string | undefined;
  try { const r = await sb(`clones?id=eq.${encodeURIComponent(row.id)}&select=v2_memory_enabled`); saved = Array.isArray(r) && r.length === 1 ? { enabled: r[0].v2_memory_enabled === true } : null; }
  catch (e) { savedProblem = columnAbsent(e) ? "the memory switch column is not on the database yet (migration not applied): memory stays off" : String((e as any)?.message ?? e).slice(0, 120); }
  const rt = (readJson(FLEET_FILE())?.girls ?? {})[slug]?.memory ?? null;
  const applied = rt?.applied ?? null;
  const inSync = !!saved && !!applied && saved.enabled === applied.enabled;
  // the queue as it is on disk right now (the fleet snapshot is up to 30 s old)
  let queue: unknown = null;
  const dead: { at: string; kind: string; code?: string; msg?: string }[] = [];
  try {
    const q = new ArchiveQueue({ file: path.join(girlDataDir(slug), "_archive_queue.jsonl"), deadFile: path.join(girlDataDir(slug), "_archive_dead.jsonl"), sink: { apply: async () => ({ ok: false, transient: true, reason: "read only" }) } });
    const st = q.stats();
    queue = { pending: st.pending, oldestPendingAt: st.oldestPendingAt ?? null, dead: st.dead, badLines: st.badLines };
    for (const d of q.deadOps().slice(-20)) dead.push({ at: d.deadAt, kind: d.op.t, ...(d.code ? { code: d.code } : {}), ...(d.msg ? { msg: d.msg } : {}) });
  } catch (e: any) { queue = { error: String(e?.message ?? e).slice(0, 120) }; }
  let totals: unknown = null, parked: unknown[] = [], runs: unknown[] = [];
  if (saved || applied) {
    try { totals = await rpc("v2mem_status", { p_creator: row.id }); } catch (e: any) { totals = notInstalled(e) ? { notInstalled: true } : { error: String(e?.message ?? e).slice(0, 120) }; }
    try { parked = await sb(`v2mem_fans?creator_id=eq.${encodeURIComponent(row.id)}&parked_until=gt.${encodeURIComponent(new Date().toISOString())}&select=fan_id,parked_until,attempts,last_error&order=parked_until.desc&limit=20`); } catch { parked = []; }
    try { runs = await sb(`v2mem_runs?creator_id=eq.${encodeURIComponent(row.id)}&select=id,fan_id,epoch,ok,tokens_in,tokens_out,cost,provider,batch_rows,facts_added,error,created_at&order=id.desc&limit=10`); } catch { runs = []; }
  }
  return { saved, savedProblem, applied, serving: rt?.serving ?? false, inSync, pending: !!saved && !inSync && row.engine === "v2", queue, runtimeQueue: rt?.queue ?? null, dead, reads: rt?.reads ?? null, worker: rt?.worker ?? null, handover: rt?.handover ?? null, totals, parked, runs };
}

/**
 * A CURRENT PREVIEW for a stored turn: today's prompt parts and today's applied settings, next to the settings that row was sent with. It is a
 * different thing from the stored request and says so; nothing in a stored request is ever rebuilt from it.
 */
export async function requestPreview(turnId: string | null) {
  const row = requestByTurn(turnId);
  if (row?.error) return row;
  const d = await details(currentGirl());
  const fleet = (readJson(FLEET_FILE())?.girls ?? {})[currentGirl()] ?? {};
  return {
