  };
}

const json = (res: http.ServerResponse, body: unknown) => {
  res.writeHead(200, { "content-type": "application/json", "cache-control": "no-store" });
  res.end(JSON.stringify(body));
};

const readBody = (req: http.IncomingMessage) => new Promise<string>((ok, bad) => {
  let body = "";
  req.on("data", (c) => { body += c; if (body.length > 200_000) req.destroy(); });
  req.on("end", () => ok(body)); req.on("error", bad);
});
const fail = (res: http.ServerResponse, e: unknown) => { if (!res.headersSent) { res.writeHead(500); res.end(String((e as Error)?.message ?? e)); } };

const server = (host: string) => http.createServer((req, res) => {
  const u = new URL(req.url ?? "/", "http://x");
  // Per-girl views: ?girl=<slug> picks whose data/ and logs/ folders are read (default: the local test girl).
  const slug = (u.searchParams.get("girl") ?? "").replace(/[^a-z0-9-]/gi, "") || config.girl;
  return runAs(slug, () => route(req, res, u));
}).on("error", (e) => console.error(`monitor could not listen on ${host}:${PORT}: ${e.message}`))
  .listen(PORT, host, () => console.log(`monitor on http://${host}:${PORT}`));
function route(req: http.IncomingMessage, res: http.ServerResponse, u: URL) {
  try {
    if (req.method === "POST" && u.pathname === "/api/girls/engine") { void readBody(req).then((b) => setEngine(JSON.parse(b || "{}"))).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (req.method === "POST" && u.pathname === "/api/girls/credits") { void readBody(req).then((b) => saveCreditSettings(JSON.parse(b || "{}"))).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (u.pathname === "/api/tips") { void tipsFor(currentGirl()).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (u.pathname === "/api/memory") { void memoryFor(currentGirl()).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (u.pathname === "/api/request" && u.searchParams.get("preview") === "1") { void requestPreview(u.searchParams.get("turn")).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (u.pathname === "/api/credits") { void creditsFor(currentGirl()).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (req.method === "POST" && u.pathname === "/api/girls/details") { void readBody(req).then((b) => saveDetails(JSON.parse(b || "{}"))).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (u.pathname === "/api/girls") { void girls().then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (u.pathname === "/api/girls/map") { void mapDetails(currentGirl()).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (u.pathname === "/api/girls/details") { void details(currentGirl()).then((r) => json(res, r)).catch((e) => fail(res, e)); return; }
    if (req.method === "POST" && u.pathname === "/api/vars") {
      let body = "";
      req.on("data", (c) => { body += c; if (body.length > 200_000) req.destroy(); });
      req.on("end", () => { try { json(res, saveVars(body)); } catch (e) { res.writeHead(500); res.end(String(e)); } });
      return;
    }
    if (req.method !== "GET") { res.writeHead(405); return res.end(); }
    if (u.pathname === "/twin") {
      res.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
      return res.end(fs.readFileSync(path.join(ROOT, "dashboard", "twin.html"), "utf8").replace("</head>", "<script>" + fs.readFileSync(path.join(ROOT, "dashboard", "history-client.js"), "utf8") + "</script></head>"));
    }
    if (u.pathname === "/chat") {
      res.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
      return res.end(fs.readFileSync(path.join(ROOT, "dashboard", "chat.html"), "utf8").replace("</head>", "<script>" + fs.readFileSync(path.join(ROOT, "dashboard", "history-client.js"), "utf8") + "</script></head>"));
    }
    if (u.pathname === "/") {
      res.writeHead(200, { "content-type": "text/html; charset=utf-8", "cache-control": "no-store" });
      return res.end(fs.readFileSync(path.join(ROOT, "dashboard", "index.html")));
    }
    if (u.pathname === "/api/status") return json(res, status());
    if (u.pathname === "/api/turns") {
      const all = turns();
      return json(res, { stats: stats(all), turns: all.slice(0, Number(u.searchParams.get("limit") ?? 300)) });
    }
    if (u.pathname === "/api/request") return json(res, requestByTurn(u.searchParams.get("turn")));
    if (u.pathname === "/api/chats") return json(res, chats());
    if (u.pathname === "/api/chat-history") {
      const chatId = u.searchParams.get("chatId") ?? "";
      if (!/^-?\d{1,16}$/.test(chatId) || !fs.existsSync(path.join(girlDataDir(), `${chatId}.json`))) { res.writeHead(404); res.end("chat not found"); return; }
      void chatHistory(girlLogDir(), chatId, u.searchParams.get("before")).then(r => json(res, r)).catch(e => fail(res, e));
      return;
    }
    if (u.pathname === "/api/sales") return json(res, sales());
    if (u.pathname === "/api/bundles") return json(res, bundlesInfo() ?? { at: null, listed: [], excluded: [] });
    if (u.pathname === "/api/fans") return json(res, fans());
    if (u.pathname === "/api/prompt") return json(res, prompt());
    if (u.pathname === "/api/blocked") return json(res, readJsonl(path.join(girlLogDir(), "blocked.jsonl")).reverse());
    if (u.pathname === "/api/logs") return json(res, readLines(path.join(LOG_ROOT, "bot.out")).slice(-500));
    res.writeHead(404); res.end("not found");
  } catch (e) {
    res.writeHead(500); res.end(String(e));
  }
}

