// ---------- fake Telegram: a transport UNDER grammY's real Api ----------
type Call = { n: number; nth: number; method: string; payload: any };
type Reply = undefined | "ack" | { err: Error } | { rej: [number, string, any?] };
const showVal = (v: any): any => {
  if (v instanceof InputFile) return `[upload ${(v as any).filename ?? ""}]`;
  if (Array.isArray(v)) return v.map(showVal);
  if (v && typeof v === "object") return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, showVal(x)]));
  return v;
};
class FakeTelegram {
  calls: Call[] = [];
  private counts = new Map<string, number>();
  private static mid = 1000; // shared, so two creators' fake Telegrams never hand out the same file id
  handlers: ((c: Call) => Reply | Promise<Reply>)[] = [];
  api: Api;
  constructor(api?: Api) {
    this.api = api ?? new Api("1:fake");
    this.api.config.use(async (_prev, method, payload: any) => {
      const nth = (this.counts.get(method) ?? 0) + 1; this.counts.set(method, nth);
      const c: Call = { n: this.calls.length + 1, nth, method, payload: showVal(payload) };
      this.calls.push(c);
      for (const h of this.handlers) {
        const r = await h(c);
        if (r !== undefined) return this.respond(r, method, payload) as any;
      }
      return this.respond("ack", method, payload) as any;
    });
  }
  private respond(r: Reply, method: string, p: any) {
    if (r && typeof r === "object" && "err" in r) throw r.err;
    if (r && typeof r === "object" && "rej" in r) return { ok: false, error_code: r.rej[0], description: r.rej[1], parameters: r.rej[2] };
    const id = ++FakeTelegram.mid;
    const chat = { id: p?.chat_id, type: "private" };
    switch (method) {
      case "sendMessage": return { ok: true, result: { message_id: id, date: 0, chat, text: p.text } };
      case "sendPhoto": return { ok: true, result: { message_id: id, date: 0, chat, photo: [{ file_id: `PH${id}s`, file_unique_id: "u", width: 1, height: 1 }, { file_id: `PH${id}`, file_unique_id: "u2", width: 2, height: 2 }] } };
      case "sendVideo": return { ok: true, result: { message_id: id, date: 0, chat, video: { file_id: `VI${id}`, file_unique_id: "u", width: 1, height: 1, duration: 1 } } };
      case "sendPaidMedia": {
        const m = (p.media ?? [])[0];
        const pm = m?.type === "video" ? { type: "video", video: { file_id: `PMV${id}`, file_unique_id: "u", width: 1, height: 1, duration: 1 } }
          : { type: "photo", photo: [{ file_id: `PMP${id}s`, file_unique_id: "u", width: 1, height: 1 }, { file_id: `PMP${id}`, file_unique_id: "u2", width: 2, height: 2 }] };
        return { ok: true, result: { message_id: id, date: 0, chat, paid_media: { star_count: p.star_count, paid_media: [pm] } } };
      }
      default: return { ok: true, result: true };
    }
  }
  of(method: string) { return this.calls.filter((c) => c.method === method); }
  get methods() { return this.calls.map((c) => c.method); }
  get texts() { return this.of("sendMessage").map((c) => c.payload.text as string); }
  get mediaCalls() { return this.calls.filter((c) => ["sendPaidMedia", "sendPhoto", "sendVideo"].includes(c.method)); }
  /** Script the answer for matching calls. The first handler that returns something wins. */
  on(method: string, f: (c: Call) => Reply | Promise<Reply>) { this.handlers.push((c) => (c.method === method ? f(c) : undefined)); }
}
const rejection = (code: number, description: string, parameters?: any): Reply => ({ rej: [code, description, parameters] });
const gram = (code: number, description: string, method = "sendPaidMedia") => new GrammyError(`Call to '${method}' failed!`, { ok: false, error_code: code, description } as any, method, {});
const timeout = (method = "sendPaidMedia"): Reply => ({ err: new HttpError(`Network request for '${method}' failed!`, new Error("ETIMEDOUT")) });
const gate = <T = void>() => { let open!: (v: T) => void; const p = new Promise<T>((r) => (open = r)); return { p, open }; };
