function trace(id: string, label: string, rig: Rig, chatId: number) {
  if (!process.env.DELIVERY_TRACES) return;
  const c = rig.chat(chatId), row = rig.rows().filter((r) => String(r.chatId) === String(chatId)).at(-1);
  let st: any, fan: any;
  try { st = runAs(rig.slug, () => dash.stats(dash.turns()).allTime); fan = runAs(rig.slug, () => dash.fans()).find((f: any) => f.chatId === String(chatId)); } catch (e: any) { st = { error: String(e?.message ?? e).slice(0, 80) }; } // e.g. a chat file made unreadable on purpose
  traces.push({
    id, label,
    apiCalls: rig.tg.calls.map(brief),
    savedHistory: hist(c), sentList: c?.sent ?? [],
    requestRow: row && { turnId: row.turnId ? "<uuid>" : undefined, mode: row.mode, route: row.route, note: row.note, modelRequest: row.modelRequest, raw: row.raw, generated: row.generated, final: row.final, media: row.media, selectedMedia: row.selectedMedia, delivery: row.delivery },
    dashboard: st.error ? st : { confirmedLocked: st.lockedSent, confirmedFree: st.freeSent, selectedButNotConfirmed: st.mediaNotConfirmed, unverified: st.unverified, fanOffered: fan?.offered },
  });
}
const say1 = (rig: Rig, fan: string, her: string, chatId = nextChat(), route: Route = {}) => { M.reply = her; return rig.fan(chatId, fan, route).then(() => chatId); };

const dash = await import("../dashboard/server.js");

