// A06. Long media caption
// ===================================================================================================================
await crashed("A06", async () => {
  const long = Array.from({ length: 20 }, (_, i) => `this is flirty sentence number ${i} about how much i missed you today.`).join(" "); // ~1,400 chars, no repeated parts
  for (const [label, cat, tag, method] of [["locked", CAT, "[photo 1]", "sendPaidMedia"], ["free", CAT_F, "[free photo]", "sendPhoto"]] as const) {
    const rig = await newRig({ catalogue: cat }); const chat = nextChat(); D.calls.length = 0;
    await say1(rig, "hey", `${long} ${tag}`, chat);
    const call = rig.tg.of(method)[0], cap: string = call?.payload.caption ?? "", c = rig.chat(chat);
    ok("A06", rig.tg.of(method).length === 1 && rig.tg.texts.length === 0 && rig.tg.methods.indexOf("sendMessage") === -1, `A06 long ${label} caption: one attachment, no text-first message`);
    ok("A06", cap.length > 0 && cap.length <= CAPTION_MAX && long.startsWith(cap) && /[.!?]$/.test(cap), `A06 long ${label} caption: bounded to ${CAPTION_MAX} units, ends on a complete sentence (${cap.length})`);
    ok("A06", lastAssistant(c)!.startsWith(cap) && !lastAssistant(c)!.includes(long.slice(cap.length - 5, cap.length + 40)), `A06 long ${label} caption: the saved caption is the one actually sent`);
    ok("A06", lastRow(rig).final?.[0] === cap && lastRow(rig).delivery?.captionTrimmed?.from === long.length, `A06 long ${label} caption: the logged caption matches and records the trim`, { newOnly: true });
    trace("A06", `long ${label} caption (1,400 chars in, bounded caption out)`, rig, chat);
  }
  // the trim function itself
  const eq = (a: string, b: string) => a === b;
  ok("A06", eq(trimCaption("short"), "short") && eq(trimCaption("x".repeat(1000)), "x".repeat(1000)), "A06 trim: text up to 1000 units is untouched");
  const t1 = trimCaption("a".repeat(1500));
  ok("A06", t1.length === 1000, "A06 trim: one huge word is cut at exactly 1000");
  const words = ("word ".repeat(300)).trim();
  const t2 = trimCaption(words);
  ok("A06", t2.length <= 1000 && words.startsWith(t2) && /word$/.test(t2) && words[t2.length] === " ", "A06 trim: with no sentence end the cut falls on a whole word");
  const sent = ("hello there you. " + "x".repeat(10)).repeat(60);
  const t3 = trimCaption(sent);
  ok("A06", t3.length <= 1000 && /\.$/.test(t3), "A06 trim: prefers the end of a complete sentence");
  const pair = "😈"; // two UTF-16 units
  const t4 = trimCaption("a".repeat(999) + pair + "b".repeat(50));
  ok("A06", t4.length <= 1000 && !/[\ud800-\udbff]$/.test(t4) && !/(^|[^\ud800-\udbff])[\udc00-\udfff]/.test(t4), "A06 trim: never splits a surrogate pair at the boundary");
  const t5 = trimCaption("a".repeat(998) + pair + "b".repeat(50));
  ok("A06", t5.length <= 1000 && t5.includes(pair), "A06 trim: keeps a whole pair that fits");
  ok("A06", trimCaption(sent) === trimCaption(sent), "A06 trim: deterministic");
});

