  const rf = await newRig(); const cf = nextChat(); const g2 = gate();
  rf.tg.on("sendPaidMedia", async () => { await g2.p; return timeout(); });
  M.reply = "unlock this one [photo 1]"; rf.fanNow(cf, "hey"); await until(() => rf.tg.of("sendPaidMedia").length === 1);
  rf.reset(cf); g2.open(); await rf.idle();
  ok("A13", rf.tg.texts.length === 0 && hist(rf.chat(cf)).length === 0, "A13 reset + in-flight timeout: no recovery text, nothing written back");
  ok("A13", lastRow(rf).delivery?.media?.status === "unknown" && lastRow(rf).delivery.recovery?.suppressed !== undefined, "A13 reset + in-flight timeout: outcome recorded as unknown, recovery suppressed", { newOnly: true });
  // runner stop during an in-flight request
  const rs = await newRig(); const cs = nextChat(); const g3 = gate();
  rs.tg.on("sendPaidMedia", async () => { await g3.p; return rejection(400, "Bad Request: PAID_MEDIA_INVALID"); });
  M.reply = "unlock this one [photo 1]"; rs.fanNow(cs, "hey"); await until(() => rs.tg.of("sendPaidMedia").length === 1);
  rs.stop(); g3.open(); await rs.idle();
  ok("A13", rs.tg.of("sendPaidMedia").length === 1 && rs.tg.texts.length === 0, "A13 runner stop during the request: no later sends (no recovery text, no retry)");
  ok("A13", lastRow(rs).delivery?.cancelled?.reason === "stopped" && lastRow(rs).delivery.media?.status === "rejected", "A13 runner stop during the request: the rejection and the stop are recorded", { newOnly: true });
  // runner stop while an ACCEPTED request is in flight: the message is out, so it is recorded as it happened (the chat was not reset); nothing more is sent
  const ra = await newRig(); const ca = nextChat(); const g4 = gate();
  ra.tg.on("sendPaidMedia", async () => { await g4.p; return "ack" as const; });
  M.reply = "unlock this one [photo 1]"; ra.fanNow(ca, "hey"); await until(() => ra.tg.of("sendPaidMedia").length === 1);
  ra.stop(); g4.open(); await ra.idle();
  ok("A13", ra.tg.of("sendPaidMedia").length === 1 && ra.tg.texts.length === 0, "A13 runner stop while the request is accepted: no later sends");
  ok("A13", hist(ra.chat(ca)).filter((h) => h.startsWith("assistant:")).length === 1 && ra.chat(ca).sent.join() === "photo:p1", "A13 runner stop while the request is accepted: the accepted card is recorded once (no reset happened, so the history is not stale)");
  ok("A13", lastRow(ra).delivery?.cancelled?.reason === "stopped" && lastRow(ra).delivery.media?.status === "acknowledged" && lastRow(ra).media?.key === "photo:p1", "A13 runner stop while the request is accepted: row says stopped and keeps the acknowledged outcome", { newOnly: true });
  // stop clears pending timers: nothing queued ever starts
  const rp = await newRig({ mergeMs: 400 }); const cp = nextChat(); M.requests.length = 0; const tb = timerCount(); rp.fanNow(cp, "queued line"); const tq = timerCount(); rp.stop(); const ta = timerCount(); await new Promise((r) => setTimeout(r, 30));
  ok("A13", M.requests.length === 0 && rp.tg.calls.length === 0, "A13 stopping a runner: queued input never starts");
