  ok("P01", /never resent; the only automatic repeat is one re-upload when Telegram explicitly rejects a remembered file reference/.test(how) && !/the file is not resent/.test(how), "P01 /start text: states the one permitted repeat (the cached-reference upload retry) instead of promising a file is never resent", { newOnly: true });
  ok("P01", parts[1].startsWith("[PROMPT TEMPLATE PREVIEW, not a complete request]") && /TEMPLATE PREVIEW, not a complete request/.test(how), "P01 /start text: the prompt is labelled a template preview, not a complete request", { newOnly: true });
  ok("P01", parts.every((p) => p.length <= 4096), "P01 /start text: every part fits a Telegram message", { newOnly: true });
  ok("P01", !/One AI call per message/.test(how) && !/list of 5 items/.test(how), "P01 /start text: the old claims are gone", { newOnly: true });
  const idx = fs.readFileSync(new URL("../dashboard/index.html", import.meta.url), "utf8"), twin = fs.readFileSync(new URL("../dashboard/twin.html", import.meta.url), "utf8");
  ok("P02", /PREVIEW of the prompt template/.test(idx) && /not a request/.test(idx), "P02 the local prompt editor is labelled a preview, not a request", { newOnly: true });
  ok("P02", /Prompt preview/.test(twin) && /not a sent request/.test(twin), "P02 the Bot V2 details editor is labelled a preview, not a sent request", { newOnly: true });
  ok("P02", !/ sent 24h/.test(twin) && /confirmed 24h/.test(twin) && /Picks up to 5 available/.test(twin), "P02 the dashboard no longer calls selected media 'sent': counts say confirmed / unverified", { newOnly: true });
});

// ---------- report ----------
process.stdout.write = realWrite as any; console.error = origErr;
const byId: Record<string, Res[]> = {};
for (const r of results) (byId[r.id] ??= []).push(r);
const fails = results.filter((r) => !r.ok);
if (process.env.DELIVERY_VERBOSE || MODE === "old") for (const r of results) say(`${r.ok ? "PASS" : "FAIL"} ${r.name}`);
else for (const r of fails) say(`FAIL ${r.name}`);
say(`\n${MODE === "old" ? "OLD-BEHAVIOUR RUN. " : ""}delivery checks by id: ` + Object.keys(byId).sort().map((id) => `${id} ${byId[id].filter((r) => r.ok).length}/${byId[id].length}`).join("  "));
if (process.env.DELIVERY_RESULTS) fs.writeFileSync(process.env.DELIVERY_RESULTS, JSON.stringify(results, null, 1));
if (process.env.DELIVERY_TRACES) fs.writeFileSync(process.env.DELIVERY_TRACES, JSON.stringify(traces, null, 1));
say(fails.length ? `\n${fails.length} FAILED of ${results.length}` : `all ${results.length} delivery checks passed`);
globalThis.fetch = realFetch;
fs.rmSync(tmp, { recursive: true, force: true });
process.exit(MODE === "old" ? 0 : fails.length ? 1 : 0);
